new:
        assert!(!serde_json::to_string(&representation)
            .expect("representation JSON")
            .contains("windows-runtime"));
    }

    fn representation(name: &str) -> CampaignRepresentation {
        CampaignRepresentation {
            backend_id: "gameengine-managed-llama-cpp".to_owned(),
            model_id: name.to_owned(),
            model_version: format!("sha256-{name}"),
            quantization: "Q4_K_M".to_owned(),
            representation_size_bytes: 1_000,
        }
    }

    fn hardware() -> BenchmarkHardwareIdentity {
        BenchmarkHardwareIdentity {
            platform: "windows-x86_64".to_owned(),
            gpu: TelemetryValue::Measured("test gpu".to_owned()),
            total_gpu_memory_bytes: TelemetryValue::Measured(12_000),
            total_system_memory_bytes: TelemetryValue::Measured(32_000),
        }
    }

    fn runtime(environment: CampaignExecutionEnvironment) -> CampaignRuntimeIdentity {
        CampaignRuntimeIdentity {
            execution_environment: environment,
            backend_runtime_version: format!("llama.cpp@test;env={}", environment.identity()),
        }
    }

    fn plan() -> BenchmarkCampaignPlan {
        BenchmarkCampaignPlan {
            schema_version: CAMPAIGN_SCHEMA_VERSION,
            corpus_version: BENCHMARK_CORPUS_VERSION.to_owned(),
            benchmark_harness_version: BENCHMARK_HARNESS_VERSION.to_owned(),
            campaign_harness_version: CAMPAIGN_HARNESS_VERSION.to_owned(),
            schedule_version: CAMPAIGN_SCHEDULE_VERSION.to_owned(),
            candidates: vec![
                CampaignCandidate {
                    representation: representation("model-a"),
                    source: CampaignCandidateSource::installed(),
                },
                CampaignCandidate {
                    representation: representation("model-b"),
                    source: CampaignCandidateSource::installed(),
                },
            ],
            runtime_identities: vec![runtime(CampaignExecutionEnvironment::WindowsNative)],
            tasks: BENCHMARK_TASKS
                .iter()
                .take(2)
                .enumerate()
                .map(|(index, task)| {
                    CampaignTaskPlan::for_task(task.id, 100 + index as u64).expect("task plan")
                })
                .collect(),
            repetitions: 2,
            comparison_class: CampaignComparisonClass::ModelComparison,
            execution_profile: CampaignExecutionProfile::Warm,
            quality: QualityPreference::Balanced,
            hardware: hardware(),
            workload_policy_version: WORKLOAD_POLICY_VERSION.to_owned(),
            sampling_profile: "provider-default-uncontrolled".to_owned(),
            seed_policy: CampaignSeedPolicy::ProviderUnavailable,
        }
    }

    fn installed(plan: &BenchmarkCampaignPlan) -> Vec<BenchmarkModelIdentity> {
        plan.candidates
            .iter()
            .map(|candidate| BenchmarkModelIdentity {
                backend_id: candidate.representation.backend_id.clone(),
                model_id: candidate.representation.model_id.clone(),
                model_version: TelemetryValue::Measured(
                    candidate.representation.model_version.clone(),
                ),
                quantization: TelemetryValue::Measured(
                    candidate.representation.quantization.clone(),
                ),
                representation_size_bytes: TelemetryValue::Measured(
                    candidate.representation.representation_size_bytes,
                ),
                backend_runtime_version: TelemetryValue::Measured(
                    "runtime intentionally ignored by acquisition".to_owned(),
                ),
            })
            .collect()
    }

    #[test]
    fn schedule_is_deterministic_and_interleaves_models() {
        let plan = plan();
        let first = plan.schedule().expect("schedule");
        assert_eq!(first, plan.schedule().expect("same schedule"));
        assert_eq!(first[0].candidate_index, 0);
        assert_eq!(first[1].candidate_index, 1);
    }

    #[test]
    fn runtime_characterization_uses_one_representation_and_two_environments() {
        let mut plan = plan();
        plan.candidates.truncate(1);
        plan.runtime_identities = vec![
            runtime(CampaignExecutionEnvironment::WindowsNative),
            runtime(CampaignExecutionEnvironment::Wsl2Linux),
        ];
        plan.comparison_class = CampaignComparisonClass::RuntimeCharacterization;
        assert!(plan.validate().is_ok());
        let schedule = plan.schedule().expect("schedule");
        assert_eq!(schedule[0].candidate_index, 0);
        assert_eq!(schedule[1].candidate_index, 0);
        assert_ne!(
            schedule[0].execution_environment,
            schedule[1].execution_environment
        );
    }

    #[test]
    fn measured_failure_is_not_retried_as_pre_measurement_noise() {
        let mut campaign = BenchmarkCampaign::new(plan()).expect("campaign");
        let installed = installed(&campaign.plan);
        campaign.start(&installed).expect("start");
        let request = campaign.begin_next_run().expect("next").expect("request");
        campaign.mark_measurement_started(&request).expect("measure");
        assert!(campaign.record_pre_measurement_failure(&request).is_err());
        campaign
            .fail_measured_run(&request, CampaignFailureKind::ValidationFailure)
            .expect("failure retained");
        assert_eq!(campaign.runs[0].status, CampaignRunStatus::Failed);
    }
